  `executed_at` date DEFAULT NULL COMMENT \'Data di esecuzione effettiva\',
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT \'planned\' COMMENT \'Stato: planned, in_progress, completed, cancelled\',
  `protocol_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Numero di protocollo ufficiale (es. OAM)\',
