  `execution_method` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT \'documentale\' COMMENT \'Metodo: documentale, in_loco, intervista\',
  `scope` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT \'Ambito oggettivo del controllo\',
  `outcome` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Esito: Passato, Con Rilievi, Fallito\',
