  `documentable_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT \'Alias del modello a cui è collegato il documento (morph map)\',
  `documentable_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT \'ID del record a cui è collegato il documento\',
  `document_type_id` bigint unsigned DEFAULT NULL COMMENT \'Tipo di documento di riferimento\',
  `document_requirement_id` bigint unsigned DEFAULT NULL COMMENT \'Requisito del plico (task) da cui nasce il documento: fase, ruoli e chi firma\',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Titolo logico o nome file del documento\',
  `training_hours` int DEFAULT NULL COMMENT \'Ore di formazione richieste\',
  `training_organization` enum(\'interna\',\'OAM\',\'IVASS\',\'PRIVACY\') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Formazione per organizzazione\',
  `docnumber` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Numero protocollo o identificativo del documento\',
  `spatie_collection` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT \'default\' COMMENT \'Nome della collection per Spatie Media Library\',
  `document_url` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'URL pubblico o percorso del documento sul web/storage\',
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT \'caricato\' COMMENT \'Valori di DocumentStatus: na, richiesto, caricato, approvato, respinto, provvisorio, scaduto, illegibile, revocato, anomalo, integrativo; fasi della firma: dati_mancanti, stampare, scaricare, da_inviare_otp, inviato_otp, firmato_otp, da_approvare_otp\',
  `responsible_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'Alias MorphMap di chi deve far proseguire l\'\'iter del documento (client, fornitore, employee, cliente = istituto)\',
  `responsible_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT \'ID di chi deve far proseguire l\'\'iter del documento\',
  `last_sent_at` timestamp NULL DEFAULT NULL COMMENT \'Data e ora ultimo sollecito inviato\',
